CREATE TABLE finops_compute_optimizer_export_snapshots (generation_id text PRIMARY KEY CHECK (generation_id ~ '^coh_[a-f0-9]{64}$'),org_id text NOT NULL REFERENCES organizations(id) ON DELETE CASCADE,customer_id text NOT NULL REFERENCES customers(id) ON DELETE CASCADE,connection_id text NOT NULL REFERENCES aws_connections(id) ON DELETE CASCADE,materialization_id text NOT NULL CHECK (materialization_id ~ '^com_[a-f0-9]{64}$'),management_account_id text NOT NULL CHECK (management_account_id ~ '^[0-9]{12}$'),source_state text NOT NULL CHECK (source_state='COMPLETE'),complete boolean NOT NULL CHECK (complete),content_sha256 text NOT NULL CHECK (content_sha256 ~ '^[a-f0-9]{64}$'),snapshot_json text NOT NULL CHECK (octet_length(snapshot_json) BETWEEN 2 AND 268435456),generated_at text NOT NULL CHECK (char_length(generated_at)=24),recommendation_count bigint NOT NULL CHECK (recommendation_count BETWEEN 0 AND 100000),export_object_count bigint NOT NULL CHECK (export_object_count BETWEEN 1 AND 2000),created_at bigint NOT NULL CHECK (created_at BETWEEN 0 AND 9007199254740991),UNIQUE(org_id,customer_id,connection_id,materialization_id));
CREATE INDEX finops_compute_optimizer_export_history_idx ON finops_compute_optimizer_export_snapshots(org_id,customer_id,connection_id,generated_at DESC,generation_id DESC);
CREATE TABLE finops_compute_optimizer_export_heads(org_id text NOT NULL,customer_id text NOT NULL,connection_id text NOT NULL,active_generation_id text NOT NULL UNIQUE REFERENCES finops_compute_optimizer_export_snapshots(generation_id),advanced_at bigint NOT NULL CHECK (advanced_at BETWEEN 0 AND 9007199254740991),PRIMARY KEY(org_id,customer_id,connection_id));
CREATE OR REPLACE FUNCTION finops_compute_optimizer_export_snapshot_immutable() RETURNS trigger AS $$ BEGIN RAISE EXCEPTION 'FINOPS_COMPUTE_OPTIMIZER_EXPORT_SNAPSHOT_IMMUTABLE'; END; $$ LANGUAGE plpgsql;
CREATE TRIGGER finops_compute_optimizer_export_snapshots_update_guard BEFORE UPDATE ON finops_compute_optimizer_export_snapshots FOR EACH ROW EXECUTE FUNCTION finops_compute_optimizer_export_snapshot_immutable();
CREATE TRIGGER finops_compute_optimizer_export_snapshots_delete_guard BEFORE DELETE ON finops_compute_optimizer_export_snapshots FOR EACH ROW EXECUTE FUNCTION finops_compute_optimizer_export_snapshot_immutable();
CREATE OR REPLACE FUNCTION finops_compute_optimizer_export_head_guard() RETURNS trigger AS $$ DECLARE candidate finops_compute_optimizer_export_snapshots%ROWTYPE;DECLARE active finops_compute_optimizer_export_snapshots%ROWTYPE;BEGIN SELECT * INTO candidate FROM finops_compute_optimizer_export_snapshots WHERE generation_id=NEW.active_generation_id;IF candidate.generation_id IS NULL OR NOT candidate.complete OR candidate.org_id<>NEW.org_id OR candidate.customer_id<>NEW.customer_id OR candidate.connection_id<>NEW.connection_id THEN RAISE EXCEPTION 'FINOPS_COMPUTE_OPTIMIZER_EXPORT_HEAD_REJECTED';END IF;IF TG_OP='UPDATE' THEN IF NEW.org_id<>OLD.org_id OR NEW.customer_id<>OLD.customer_id OR NEW.connection_id<>OLD.connection_id THEN RAISE EXCEPTION 'FINOPS_COMPUTE_OPTIMIZER_EXPORT_HEAD_REJECTED';END IF;SELECT * INTO active FROM finops_compute_optimizer_export_snapshots WHERE generation_id=OLD.active_generation_id;IF NOT(candidate.generated_at>active.generated_at OR(candidate.generated_at=active.generated_at AND candidate.generation_id>active.generation_id))THEN RAISE EXCEPTION 'FINOPS_COMPUTE_OPTIMIZER_EXPORT_HEAD_REJECTED';END IF;END IF;RETURN NEW;END;$$ LANGUAGE plpgsql;
CREATE TRIGGER finops_compute_optimizer_export_heads_write_guard BEFORE INSERT OR UPDATE ON finops_compute_optimizer_export_heads FOR EACH ROW EXECUTE FUNCTION finops_compute_optimizer_export_head_guard();
CREATE TRIGGER finops_compute_optimizer_export_heads_delete_guard BEFORE DELETE ON finops_compute_optimizer_export_heads FOR EACH ROW EXECUTE FUNCTION finops_compute_optimizer_export_snapshot_immutable();
REVOKE ALL ON finops_compute_optimizer_export_snapshots FROM PUBLIC;
REVOKE ALL ON finops_compute_optimizer_export_heads FROM PUBLIC;
